SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');
SET @prov5 := (SELECT hoscode FROM sys_config c INNER JOIN chospital h ON c.provincecode=h.provcode AND h.hostype in(1));
SET @yearpop:=(SELECT max(b_year) FROM k_mental_pop WHERE cat_id ='f20');

CREATE TABLE IF NOT EXISTS s_mental_f20(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) NOT NULL,
  date_com varchar(14) NOT NULL,
  b_year varchar(4) NOT NULL,
	pop int(10) NOT NULL DEFAULT 0,	
	k varchar(10) NOT NULL DEFAULT '',
	target int(10) NOT NULL DEFAULT 0,
	result1 int(10) NOT NULL DEFAULT 0,
	result2 int(10) NOT NULL DEFAULT 0,
	result3 int(10) NOT NULL DEFAULT 0,
	result4 int(10) NOT NULL DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

CALL AddCol('hdc','s_mental_f20','result4','int(10) NOT NULL DEFAULT 0');

DELETE FROM s_mental_f20 WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_mental_f20
(
SELECT
@id,@prov5,CONCAT(@prov_c,'000000') areacode,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,p.pop,ROUND(p.k,3),pop_k,r1.result1,r2.result2,r3.result3,r4.result4
FROM
(SELECT 
p.prov_code,p.pop,p.k,p.pop_k
FROM k_mental_pop p
WHERE p.prov_code in(@prov_c) AND cat_id IN('f20') AND b_year IN(@yearpop)
) p , 
(SELECT
provcode,COUNT(DISTINCT f.cid) as result1
FROM
tmp_f20 f INNER JOIN chospital h ON f.diag_hospcode=h.hoscode 
WHERE h.provcode in(@prov_c) AND TIMESTAMPDIFF(year,f.birth,f.diag_date_serv) >= 15 
GROUP BY h.provcode
) r1 ,
(SELECT
SUBSTR(f.final_addr,1,2) prov_code,COUNT(DISTINCT f.cid) as result2
FROM tmp_f20 f  
WHERE  TIMESTAMPDIFF(year,f.birth,f.diag_date_serv) >= 15  AND SUBSTR(f.final_addr,1,2)  in(@prov_c)
GROUP BY SUBSTR(f.final_addr,1,2) 
) r2 ,
(SELECT COUNT(DISTINCT f.cid) as result3
FROM tmp_f20 f  
WHERE  TIMESTAMPDIFF(year,f.birth,f.diag_date_serv) >= 15 
AND (LENGTH(TRIM(f.final_addr)) =0 OR ISNULL(f.final_addr))
) r3,/*รับบริการในปี*/
(SELECT COUNT(DISTINCT f.cid) as result4
FROM t_mental f INNER JOIN t_person_db p ON f.hospcode=p.HOSPCODE AND f.pid=p.pid
WHERE  f.date_serv BETWEEN @start_d AND @end_d 
AND f.DIAGCODE LIKE 'F20%' 
AND TIMESTAMPDIFF(year,p.birth,f.date_serv) >= 15 
AND SUBSTR(f.final_addr,1,2)  in(@prov_c)
) r4 

);

