SET @prov_c := ( SELECT provincecode FROM sys_config LIMIT 1 );
SET @b_year := ( SELECT yearprocess FROM sys_config LIMIT 1 );

/*นำเข้าตามหมู่บ้านในเขต*/
DROP TEMPORARY TABLE IF EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx (
typearea varchar(1) DEFAULT NULL,
PRIMARY KEY (hospcode,cid,diag_hospcode)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 IGNORE  AS
SELECT  
v.hospcode,'1' as typearea 
,f.cid,f.name,f.lname,f.birth,f.sex,f.nation,CONCAT(h.hoscode,'-',h.hosname) as diag_hospcode,f.diag_pid,f.diag_date_serv,f.diag_diagcode,f.home_addr,f.addr_addr,f.moi_addr,f.final_addr,f.source,f.hos_addr
FROM tmp_f20 f 
INNER JOIN chospital h ON f.diag_hospcode=h.hoscode
INNER JOIN (SELECT hospcode,villcode		FROM cvillage_hosp v 
										WHERE LENGTH(villcode)=8	GROUP BY SUBSTR(villcode,1,8) 
										) v 	ON SUBSTR(v.villcode,1,8)=SUBSTR(f.final_addr,1,8) 
WHERE TIMESTAMPDIFF(year,f.birth,f.diag_date_serv) >=15;
/*นำเข้าตาม person ในเขต*/
INSERT IGNORE INTO  tx
(
SELECT h.hoscode ,p.typearea
,f.cid,f.name,f.lname,f.birth,f.sex,f.nation,CONCAT(h1.hoscode,'-',h1.hosname) asdiag_hospcode,f.diag_pid,f.diag_date_serv,f.diag_diagcode,f.home_addr,f.addr_addr,f.moi_addr,f.final_addr,f.source,f.hos_addr
FROM tmp_f20 f INNER JOIN t_person_cid  p ON f.cid=p.cid 
INNER JOIN chospital h ON p.check_hosp=h.hoscode
INNER JOIN chospital h1 ON f.diag_hospcode=h1.hoscode
WHERE p.typearea IN(1,3) AND TIMESTAMPDIFF(year,f.birth,f.diag_date_serv) >=15
);
/*นำเข้าตามสถานพยาบาลที่รักษา*/
INSERT IGNORE INTO  tx
(
SELECT h.hoscode ,p.typearea
,f.cid,f.name,f.lname,f.birth,f.sex,f.nation,CONCAT(h1.hoscode,'-',h1.hosname) asdiag_hospcode,f.diag_pid,f.diag_date_serv,f.diag_diagcode,f.home_addr,f.addr_addr,f.moi_addr,f.final_addr,f.source,f.hos_addr
FROM tmp_f20 f INNER JOIN t_person_db  p ON f.diag_hospcode=p.hospcode AND f.cid=p.cid 
INNER JOIN chospital h ON p.hospcode=h.hoscode
INNER JOIN chospital h1 ON f.diag_hospcode=h1.hoscode
WHERE  TIMESTAMPDIFF(year,f.birth,f.diag_date_serv) >=15
);

SELECT
h.hoscode,h.hosname,d.typearea,d.CID,d.name,d.lname,d.birth,d.sex,d.nation,d.diag_hospcode,h.hosname,d.diag_pid,d.diag_date_serv
,d.diag_diagcode,d.home_addr,d.addr_addr,d.moi_addr,d.hos_addr,source,d.final_addr
FROM tx d INNER JOIN chospital h ON d.hospcode=h.hoscode
WHERE 1=1 {where}
